local function buildCreature(def)
	local old = workspace:FindFirstChild(def.name)
	if old then
		old:Destroy()
	end

	local model = Instance.new("Model")
	model.Name = def.name

	local scale = def.height / 10
	local root = Instance.new("Part")
	root.Name = "HumanoidRootPart"
	root.Size = Vector3.new(2, 2, 1) * scale
	root.CFrame = CFrame.new(def.offset + Vector3.new(0, 4 * scale, 0))
	root.Transparency = 1
	root.CanCollide = false
	root.Anchored = true
	root.Parent = model
	model.PrimaryPart = root

	for _, p in def.parts do
		local name, shape, size, pos, rot, color, material, lightRange = table.unpack(p)
		local part = Instance.new("Part")
		part.Name = name
		-- "Ellipsoid" = a block with a sphere SpecialMesh, which stretches to fill the part (smooth oval)
		part.Shape = shape == "Ellipsoid" and Enum.PartType.Block or Enum.PartType[shape]
		part.Size = size
		part.CFrame = CFrame.new(def.offset + pos) * CFrame.fromOrientation(math.rad(rot.X), math.rad(rot.Y), math.rad(rot.Z))
		part.Color = color
		part.Material = Enum.Material[material]
		part.TopSurface = Enum.SurfaceType.Smooth
		part.BottomSurface = Enum.SurfaceType.Smooth
		part.CanCollide = false
		part.Massless = true
		part.CastShadow = material ~= "Neon"
		part.Parent = model

		if shape == "Ellipsoid" then
			local mesh = Instance.new("SpecialMesh")
			mesh.MeshType = Enum.MeshType.Sphere
			mesh.Parent = part
		end

		local weld = Instance.new("WeldConstraint")
		weld.Part0 = root
		weld.Part1 = part
		weld.Parent = part

		if lightRange then
			local light = Instance.new("PointLight")
			light.Color = color
			light.Range = lightRange
			light.Brightness = 3
			light.Parent = part
		end
	end

	local humanoid = Instance.new("Humanoid")
	humanoid.MaxHealth = def.health
	humanoid.Health = def.health
	humanoid.DisplayName = "[" .. def.stage .. "] " .. def.name
	humanoid.Parent = model

	model.Parent = workspace
	return model
end

for _, def in CREATURES do
	buildCreature(def)
end
print("Phantom Wraiths built!")
